export const handler = async (input) => {
  // 发票内容唯一使用数据准备阶段生成的单据级 goodsName，不从其他字段回退。
  const goodsName = String(input?.goodsName ?? '');
  const context = input?.context || {};
  // LLM 后续节点需要继续使用原始票据字段生成稽核结果，不能只保留 prompt。
  const invoiceContext = {
    invoiceNo: input?.invoiceNo ?? '',
    goodsName: input?.goodsName ?? '',
    instance_code: input?.instance_code ?? null,
    invoice_file_id: input?.invoice_file_id ?? null,
    invoice_info_id: input?.invoice_info_id ?? null
  };
  const contentMissing = goodsName.trim() === '';
  const normalizedGoodsName = goodsName.replace(/[\s，。、“”‘’（）()【】\[\]：:；;、/\\_-]+/g, '');
  const rechargeCardRuleHit = !contentMissing && /(预付(?:费)?卡|充值卡|卡充值|充值|预存(?:款|费)?|储值(?:卡|账户)?|单用途卡|多用途卡|成品油卡|加油卡|购物卡|礼品卡|消费卡|福利卡|卡券|电子卡)/i.test(normalizedGoodsName);

  if (contentMissing) {
    return {
      ...invoiceContext,
      prompt: '',
      skipLlm: true,
      llmBypassResult: { passed: true },
      context
    };
  }
  if (rechargeCardRuleHit) {
    return {
      ...invoiceContext,
      prompt: '',
      skipLlm: true,
      llmBypassResult: { passed: false },
      context
    };
  }

  const optimizedPrompt = `# Role
你是一位极其严谨的企业财税合规审计专家，负责审查发票商品内容（发票内容）中是否包含公司明令禁止报销的"预付、充值、储值类卡券"项目。

# 核心审查规则
请仔细阅读给出的【发票内容】。如果内容中包含、涉及或暗示了"预付卡销售"、"充值"、"预存"、"储值"等资金前置占用的非即期消费行为，则判定为【不合规】；如果是正常的交通费消费（运输服务费、乘车费、客运服务费、通行费、汽油费、充电服务费、供电服务费、代驾费、停车费），则判定为【合规】。

# 同义词和语义扩展
- “预付卡销售”“预存款”“储值账户”“充值服务”等同义表达，均按预付/充值/储值类项目判断；
- 正常的即时交通服务消费，不因税收分类名称本身被判定为违规。

# 核心判据清单
- 【不合规（Passed = false）的特征】词：预付卡、单用途卡、充值、充值卡、预存、储值、面值、卡券、成品油(卡)。
- 【合规（Passed = true）的特征】词：运输服务费、乘车费、客运服务费、通行费、汽油费、充电服务费、供电服务费、代驾费、停车费。

# 示例参考 (Few-Shot)
- 输入：*运输服务*客运服务费 ➡️ 返回：{"passed": true}
- 输入：*现代服务*代驾费 ➡️ 返回：{"passed": true}
- 输入：*现代服务*预付卡销售 ➡️ 返回：{"passed": false}
- 输入：*现代服务*充值卡 ➡️ 返回：{"passed": false}
- 输入：*现代服务*违约金 ➡️ 返回：{"passed": false}

# 无法确定时返回 true：只有明确命中禁止项目时才判定为不合规。

# 极其严格的输出格式要求
你必须【仅仅且直接】返回一个标准的 JSON 对象，严禁包含任何前言、后记、Markdown 标记（如 json 块标签）或多余的文字解释。

JSON 结构必须严格如下：
{
  "passed": 判定结果（布尔类型 true 或 false，不要带引号）
}

# 待审查的真实数据
发票内容是：${goodsName}`;

  // 3. 返回高准确率的最终大模型提示词
  return {
    ...invoiceContext,
    prompt: optimizedPrompt,
    skipLlm: false,
    context
  };
};

import http from 'http';

export const handler = async (input) => {
  // 决策表的 message 和回写主键依赖原始票据字段。LLM 只返回判定结果，
  // 因此必须显式透传这些业务字段，避免经过 LLM 分支后上下文丢失。
  const invoiceContext = {
    invoiceNo: input?.invoiceNo ?? '',
    goodsName: input?.goodsName ?? '',
    instance_code: input?.instance_code ?? null,
    invoice_file_id: input?.invoice_file_id ?? null,
    invoice_info_id: input?.invoice_info_id ?? null
  };
  try {
    // 规则节点已经确定结果时，直接返回，不调用远端 LLM。
    if (input?.skipLlm === true) {
      return {
        ...invoiceContext,
        llm_status: 'success',
        llm_result: input.llmBypassResult || { passed: true },
        skipped: true,
        error_message: null
      };
    }

    const context = input && input.context ? input.context : {};
    if (!context.llmGatewayUrl) {
      throw new Error('llmGatewayUrl not injected in context; configure NODE_GATEWAY_URL in .env');
    }
    const LOCAL_LLM_URL = context.llmGatewayUrl;
    const prompt = input.prompt || context.prompt || (input.prev && input.prev.prompt) || '';

    if (!prompt) {
      throw new Error('missing prompt from previous component output');
    }

    const payload = { prompt };
    if (input.systemPrompt || context.systemPrompt) {
      payload.systemPrompt = input.systemPrompt || context.systemPrompt;
    }
    if (input.model || context.llmModel) {
      payload.model = input.model || context.llmModel;
    }
    if (typeof input.temperature === 'number' || typeof context.temperature === 'number') {
      payload.temperature = typeof input.temperature === 'number' ? input.temperature : context.temperature;
    }
    if (input.context && input.context.runId) { payload.runId = input.context.runId; }
    if (input.context && input.context.receiptCode) { payload.receiptCode = input.context.receiptCode; }
    if (input.context && input.context.invoiceKey) { payload.invoiceKey = input.context.invoiceKey; }
    const response = await http.post(LOCAL_LLM_URL, payload);

    if (!response || response.status < 200 || response.status >= 300) {
      throw new Error('local llm service failed at ' + LOCAL_LLM_URL + ': ' + (response && response.status ? response.status : 'unknown'));
    }

    const result = typeof response.data === 'string' ? JSON.parse(response.data) : (response.data || {});
    return {
      ...invoiceContext,
      llm_status: result.llmStatus || 'error',
      llm_result: result.llmResult || null,
      raw_content: result.rawContent || null,
      error_message: result.errorMessage || null
    };
  } catch (error) {
    return {
      ...invoiceContext,
      llm_status: 'error',
      llm_result: null,
      error_message: error && error.message ? error.message : String(error)
    };
  }
};

